&lt;span class="k"&gt;if&lt;/span&gt; &lt;span class="ow"&gt;not&lt;/span&gt; &lt;span class="n"&gt;resume_path&lt;/span&gt;&lt;span class="p"&gt;:&lt;/span&gt;
